create function pg_temp.assert_r(ok boolean)returns void language plpgsql as $$begin if ok is not true then raise exception 'reveal_assertion';end if;end$$;
create function pg_temp.deny_r(q text,c text)returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=c then return;end if;raise;end;raise exception 'expected_reveal_denial';end$$;
